function balancedCanopy(tree) {
    function build(values) {
        if (values.length === 0)
            return null;
        const root = { value: values[0], left: null, right: null };
        const queue = [root];
        let index = 1;
        while (queue.length > 0 && index < values.length) {
            const node = queue.shift();
            const left = values[index++];
            if (left !== undefined && left !== null)
                queue.push(node.left = { value: left, left: null, right: null });
            const right = values[index++];
            if (right !== undefined && right !== null)
                queue.push(node.right = { value: right, left: null, right: null });
        }
        return root;
    }
    function height(node) {
        if (node === null)
            return 0;
        return 1 + Math.max(height(node.left), height(node.right));
    }
    function balanced(node) {
        if (node === null)
            return true;
        if (Math.abs(height(node.left) - height(node.right)) > 1)
            return false;
        return balanced(node.left) && balanced(node.right);
    }
    return balanced(build(tree));
}

